#!/usr/bin/env bash
# Goal verification for: <GOAL>
# Generated by /goal-run, approved by the user. Agents must NOT edit this file:
# the Stop hook restores it if it changes. Exit 0 = goal met.
set -uo pipefail
cd "$(git rev-parse --show-toplevel)"
LOG="$(mktemp)"; trap 'rm -f "$LOG"' EXIT
fail=0
check() {
  local name="$1"; shift
  if "$@" >"$LOG" 2>&1; then echo "PASS  $name"
  else echo "FAIL  $name"; tail -n 25 "$LOG" | sed 's/^/      /'; fail=1; fi
}

BASE_REF="<base branch, e.g. main>"
BASE="$(git merge-base HEAD "$BASE_REF")"

# ── Acceptance criteria (one check per criterion, from the approved plan) ──
check "type check"       <e.g. npm run check>
check "build"            <e.g. npm run build>
check "tests"            <e.g. npm test>
# check "axe all routes" <command>

# ── Anti-gaming (keep these) ──
check "no new .only/.skip/.fixme in tests" bash -c \
  '! git diff "$1" -- <test dirs, e.g. tests e2e> | grep -E "^\+.*\.(only|skip|fixme)\("' _ "$BASE"
check "no test files deleted" bash -c \
  '[ -z "$(git diff --diff-filter=D --name-only "$1" -- <test dirs>)" ]' _ "$BASE"
check "test count >= <BASELINE>" bash -c \
  'n=$(<command printing the test count, e.g. npx playwright test --list | grep -oE "Total: [0-9]+" | grep -oE "[0-9]+">); [ "${n:-0}" -ge <BASELINE> ]'

exit $fail
